CREATE PROCEDURE `plus_one`(`x` INT64) RETURNS `result` INT64 AS {
  RETURN `x` + 1 AS `result`
}

CREATE PROCEDURE `greet`(`name` STRING, `prefix` STRING DEFAULT 'hi') RETURNS `message` STRING AS {
  RETURN `prefix` || `name` AS `message`
}

CREATE PROCEDURE `knows_in_degree`() RETURNS (`id` INT64, `score` INT64) AS {
  NODE VALUE `score` SumAgg<INT64> = 0
  TABLE `result_table` TYPED TABLE {`id` INT64, `score` INT64}
  MATCH (:`Person`)-[:`KNOWS`]->(`dst`:`Person`)
  PER PATH {
    SET `dst`.@`score` += 1
  }
  MATCH (`p`:`Person`)
  PER NODE (`p`) {
    EXPORT `p`.`id`, `p`.@`score` INTO `result_table`
  }
  FOR `r` IN `result_table`
  RETURN `r`.`id` AS `id`, `r`.`score` AS `score`
}

MATCH (`p`:`Person`)
WHERE EXISTS {
  MATCH (`p`)-[:`KNOWS`]->(:`Person`)
}
RETURN `p`.`id` AS `id`
